from decimal import Decimal

import pytest

from refproj.pricing import format_price, parse_price


def test_format_always_prints_two_decimals() -> None:
    assert format_price(Decimal("12.5")) == "12.50"
    assert format_price(Decimal("7")) == "7.00"
    assert format_price(Decimal("0.01")) == "0.01"


def test_format_of_zero_is_zero_point_zero_zero() -> None:
    assert format_price(Decimal("0")) == "0.00"


def test_format_groups_thousands_with_commas() -> None:
    assert format_price(Decimal("1234.5")) == "1,234.50"
    assert format_price(Decimal("1000000.00")) == "1,000,000.00"


def test_format_below_a_thousand_has_no_comma() -> None:
    assert format_price(Decimal("999.99")) == "999.99"


def test_format_of_max_price_is_the_upper_bound() -> None:
    assert format_price(Decimal("9999999.99")) == "9,999,999.99"


@pytest.mark.parametrize("price", [Decimal("10000000.00"), Decimal("-0.01")])
def test_format_outside_the_range_is_rejected(price: Decimal) -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(price)


@pytest.mark.parametrize("price", [Decimal("1.005"), Decimal("0.001"), Decimal("12.345")])
def test_format_does_not_round_a_fraction_of_a_cent(price: Decimal) -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(price)


def test_parse_reads_the_printed_text() -> None:
    result = parse_price("1,234.50")
    assert isinstance(result, Decimal)
    assert result == Decimal("1234.50")
    assert parse_price("0.00") == Decimal("0")
    assert parse_price("9,999,999.99") == Decimal("9999999.99")


def test_parse_reads_the_text_with_commas_left_out() -> None:
    assert parse_price("1234.50") == Decimal("1234.50")
    assert parse_price("9999999.99") == Decimal("9999999.99")


def test_parse_result_is_in_cents() -> None:
    # Seam 1: compared as text, so a result equal in value that prints as 1234.5 fails.
    assert str(parse_price("1,234.50")) == "1234.50"
    assert str(parse_price("1234.50")) == "1234.50"
    assert str(parse_price("12.00")) == "12.00"
    assert str(parse_price("0.00")) == "0.00"


